package org.jsoup.nodes;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import org.jsoup.Connection;
import org.jsoup.parser.Parser;

import java.nio.charset.Charset;
import java.util.List;

import static org.junit.Assert.*;

@RunWith(MockitoJUnitRunner.class)
public class DocumentTest {

    @Test
    public void createShellTest() {
        String baseUri = "http://example.com/";
        Document doc = Document.createShell(baseUri);
        assertNotNull(doc);
    }

    @Test
    public void locationTest() {
        String baseUri = "http://example.com/";
        Document doc = new Document(baseUri);
        assertEquals(baseUri, doc.location());
    }

    @Test
    public void connectionTest() {
        Connection connection = Connection.connect("http://example.com");
        Document doc = new Document("http://example.com").connection(connection);
        assertEquals(connection, doc.connection());
    }

    @Test
    public void documentTypeTest() {
        Document doc = new Document("http://example.com/");
        assertNull(doc.documentType());
    }

    @Test
    public void headTest() {
        String baseUri = "http://example.com/";
        Document doc = Document.createShell(baseUri);
        assertNotNull(doc.head());
    }

    @Test
    public void titleTest() {
        String baseUri = "http://example.com/";
        Document doc = Document.createShell(baseUri);
        doc.title(baseUri);
        assertEquals(baseUri, doc.title());
    }

    @Test
    public void charsetTest() {
        Document doc = new Document("http://example.com/");
        doc.charset(Charset.forName("UTF-8"));
        assertEquals(Charset.forName("UTF-8"), doc.charset());
    }

    @Test
    public void updateMetaCharsetElementTest() {
        Document doc = new Document("http://example.com/");
        doc.updateMetaCharsetElement(true);
        assertTrue(doc.updateMetaCharsetElement());
    }

    @Test
    public void cloneTest() {
        Document doc = new Document("http://example.com/");
        Document clonedDoc = doc.clone();
        assertNotNull(clonedDoc);
        assertNotSame(doc, clonedDoc);
    }

    @Test
    public void parserTest() {
        Parser parser = new Parser(new Document("http://example.com/"));
        Document doc = new Document("http://example.com/").parser(parser);
        assertEquals(parser, doc.parser());
    }  
}
